def _provider_launch_spec(
    invocation: Invocation, session_id: str | None
) -> ProviderLaunchSpec:
    options = dict(invocation.provider_options)
    try:
        env_overrides: dict[str, str] = {}
        if invocation.provider_id == "claude-code":
            # Claude Code has no -c config channel: config_overrides travel as
            # child-process env entries.  Translating here fails loud for an
            # unrepresentable entry (never a silent drop) and fills the spec's
