    if not _same_path(actual_worktree, declaration.worktree_root):
        raise GitSafetyError(
            "declared worktree_root is not the actual Git worktree root"
        )
    if not _same_path(actual_common, declaration.common_dir):
        raise GitSafetyError(
            "declared common_dir is not the actual Git common directory"
        )
    branch = _git(
        declaration.worktree_root,
        "symbolic-ref",
        "--quiet",
        "--short",
        "HEAD",
        allow_failure=True,
    )
    if branch is None:
        raise GitSafetyError("coding worktree must have an attached branch")
    if branch != declaration.branch:
        raise GitSafetyError(
            f"coding worktree branch {branch!r} does not match declared branch {declaration.branch!r}"
        )
    base = _git(
        declaration.worktree_root,
        "rev-parse",
        "--verify",
        f"{declaration.base_commit}^{{commit}}",
    )
    head = _git(declaration.worktree_root, "rev-parse", "--verify", "HEAD^{commit}")
    if (
        base is None
        or head is None
        or _HEX_COMMIT.fullmatch(base) is None
        or _HEX_COMMIT.fullmatch(head) is None
    ):
        raise GitSafetyError("Git returned an invalid commit identity")
    return GitIdentity(
        actual_common, actual_worktree, branch, base.lower(), head.lower()
    )


